    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Parameterize Merge Options",
      "activity_description": "Extend existing merge functionality with configurable options, integrate with mega-store for delta consumption, add configuration validation",
      "most_likely_effort": 14
    },
    {
